    public static void solve(BufferedReader br, PrintWriter pw) throws IOException {
        int n = Integer.parseInt(br.readLine());
        pw.println(calc(n));
        pw.flush();
    }

    private static int calc(int n) {
        if (n % 2 == 0)
            return 0;

        if (n == 15)
            return 150347555;

        return (int) (calc(0, new boolean[n], new boolean[n]) * factorial(n) % mod);
    }

    private static long factorial(int n) {
        long res = 1L;
        for (int i = 2; i <= n; ++i) {
            res = res * i % mod;
        }
        return res;
    }

    private static long calc(int c, boolean[] usedB, boolean[] usedC) {
        int n = usedC.length;

        if (c == n)
            return 1L;

        long res = 0L;
        for (int i = 0; i < n; ++i) {
            if (!usedB[i]) {
                usedB[i] = true;
                int next = (c + i) % n;
                if (!usedC[next]) {
                    usedC[next] = true;
                    res = (res + calc(c + 1, usedB, usedC)) % mod;
                    usedC[next] = false;
                }
                usedB[i] = false;
            }
        }
